# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(render(digest(shape(raw))))

